/* Training and equipment transactions; called only outside encounters. */
(function(g){'use strict';const N=g.DecideCreation||(typeof require==='function'?require('./creation-data.js'):null);const gates={B:{xp:300,wins:3,level:3,cost:100},A:{xp:900,wins:10,level:10,cost:250},S:{xp:2500,wins:25,level:20,cost:500}};
function ready(s){if(!s.character||s.character.design!==1||s.expedition||s.dead||s.event)throw Error('ต้องกลับจากสนามและจบเหตุการณ์ก่อน');}
function promote(s,key){ready(s);const c=s.character,grade=c.proficiencyGrades[key],next={C:'B',B:'A',A:'S'}[grade],gate=gates[next];if(!gate||!N.profs[key]||(c.practice[key]||0)<gate.xp||(c.victories||0)<gate.wins||c.level<gate.level||s.gold<gate.cost)throw Error('ต้องมีแรงก์ ประสบการณ์ ชัยชนะ เลเวล และค่าฝึกครบตามเงื่อนไข');s.gold-=gate.cost;c.proficiencyGrades[key]=next;return next;}
function learnSpell(s,id){ready(s);const c=s.character,a=N.skills[id];if(!['bolt','fire','frost','quagmire','lightning','wind'].includes(id)||!a?.magic||c.skills.includes(id)||c.stats.INT<10||s.gold<20)throw Error('เรียนเวทต้องมี INT 10 และ 20 เหรียญ และยังไม่เคยเรียน');s.gold-=20;c.skills.push(id);const key='skill:decide-'+id;s.learned.push(key);s.known[key]=2;}
function changeEquipment(s,main,off){ready(s);s.character.equipment=N.equip(s.character,main,off);}
function buy(s,id){ready(s);const c=s.character,w=N.weapons[id];if(!w||!N.classes[c.job].weapons.includes(w.type)||s.gold<25||c.inventory.weapons.length>=100)throw Error('ซื้อไม่ได้ ต้องมี25เหรียญและที่ว่าง');s.gold-=25;c.inventory.weapons.push(id);}
function dualReady(s){ready(s);const c=s.character;if(c.proficiencyGrades.dual)throw Error('เรียนอาวุธคู่แล้ว');const onehand=Object.values(N.weapons).filter(w=>w.hands===1&&N.classes[c.job].weapons.includes(w.type));if(!s.adventure?.forest||!onehand.some(w=>['B','A','S'].includes(c.proficiencyGrades[w.type]))||s.gold<200)throw Error('ค้นพบศาลาป่าก่อน ฝึกอาวุธมือเดียวถึง B และมี 200 เหรียญ');return onehand.find(w=>['B','A','S'].includes(c.proficiencyGrades[w.type]));}
const api={buy,gates,promote,learnSpell,changeEquipment,dualReady};g.DecideProgression=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
